    greenDark: '#08442a',
    gold: '#c9a24a',
    goldLight: '#e8c97a',
    goldDark: '#9c7a2e',
    cream: '#fdfaf2',
    white: '#ffffff',
  },
  fonts: {
    serif: '"Georgia", "Times New Roman", serif',
  },
};

