    ctx.closePath();
  },

  text(ctx, str, x, y, { font, color, align = 'center', baseline = 'alphabetic' }) {
    ctx.fillStyle = color;
    ctx.font = font;
    ctx.textAlign = align;
    ctx.textBaseline = baseline;
    ctx.fillText(str, x, y);
    ctx.textBaseline = 'alphabetic';
  },

  loadImage(src) {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => resolve(img);
      img.onerror = reject;
      img.src = src;
    });
  },
};

// ============================================================
// DECORATIVE SHAPES
// ============================================================
const shapes = {
  star(ctx, cx, cy, r, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    for (let i = 0; i < 5; i++) {
      const a1 = (Math.PI * 2 * i) / 5 - Math.PI / 2;
      const a2 = a1 + Math.PI / 5;
      const [x1, y1] = [cx + Math.cos(a1) * r, cy + Math.sin(a1) * r];
      const [x2, y2] = [cx + Math.cos(a2) * (r / 2.3), cy + Math.sin(a2) * (r / 2.3)];
      i === 0 ? ctx.moveTo(x1, y1) : ctx.lineTo(x1, y1);
      ctx.lineTo(x2, y2);
    }
    ctx.closePath();
    ctx.fill();
  },

  diamond(ctx, cx, cy, size, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(cx, cy - size);
    ctx.lineTo(cx + size, cy);
    ctx.lineTo(cx, cy + size);
    ctx.lineTo(cx - size, cy);
    ctx.closePath();
    ctx.fill();
  },

  laurel(ctx, cx, cy, color, mirror = false) {
    ctx.save();
    ctx.translate(cx, cy);
    if (mirror) ctx.scale(-1, 1);

    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    ctx.lineWidth = 2.5;

    ctx.beginPath();
    ctx.moveTo(0, -75);
    ctx.quadraticCurveTo(-45, 0, 0, 75);
    ctx.stroke();

    for (let i = -65; i <= 65; i += 14) {
      const t = (i + 65) / 130;
      const x = -Math.sin(t * Math.PI) * 45;
      ctx.save();
      ctx.translate(x, i);
      ctx.rotate(-Math.PI / 4 - 0.2);
      ctx.beginPath();
      ctx.ellipse(-9, 0, 11, 4.5, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
  },

  ornamentLine(ctx, cx, cy, width, color) {
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    ctx.moveTo(cx - width / 2, cy);
    ctx.lineTo(cx - 18, cy);
    ctx.moveTo(cx + 18, cy);
    ctx.lineTo(cx + width / 2, cy);
    ctx.stroke();

    shapes.diamond(ctx, cx, cy, 6, color);

    ctx.beginPath();
    ctx.arc(cx - 13, cy, 2, 0, Math.PI * 2);
    ctx.arc(cx + 13, cy, 2, 0, Math.PI * 2);
    ctx.fill();
  },

  sideOrnament(ctx, cx, cy, color) {
    shapes.diamond(ctx, cx, cy, 10, color);
    ctx.beginPath();
    ctx.arc(cx, cy - 18, 2.5, 0, Math.PI * 2);
    ctx.arc(cx, cy + 18, 2.5, 0, Math.PI * 2);
    ctx.fill();
  },
};

// ============================================================
// FRAME COMPONENTS (each draws one section)
// ============================================================
const drawBackground = (ctx) => {
  const { width: W, height: H } = CANVAS;
  const grad = ctx.createLinearGradient(0, 0, 0, H);
  grad.addColorStop(0, THEME.colors.green);
  grad.addColorStop(1, THEME.colors.greenDark);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);
};

const drawCreamPanel = (ctx) => {
  const { width: W } = CANVAS;
  const { inset, topRadius, creamBottomY } = LAYOUT;

  ctx.fillStyle = THEME.colors.cream;
  ctx.beginPath();
  ctx.moveTo(inset, topRadius + inset);
  ctx.quadraticCurveTo(inset, inset, inset + topRadius, inset);
  ctx.lineTo(W - inset - topRadius, inset);
  ctx.quadraticCurveTo(W - inset, inset, W - inset, topRadius + inset);
  ctx.lineTo(W - inset, creamBottomY);
  ctx.quadraticCurveTo(W / 2, creamBottomY + 90, inset, creamBottomY);
  ctx.closePath();
  ctx.fill();
};

const drawGoldFrame = (ctx) => {
  const { width: W } = CANVAS;
  const { inset, topRadius, creamBottomY } = LAYOUT;

  const drawFrame = (offset, lineWidth, strokeStyle) => {
    const x = inset + offset;
    const y = inset + offset;
    const w = W - 2 * (inset + offset);
    ctx.strokeStyle = strokeStyle;
    ctx.lineWidth = lineWidth;
    ctx.beginPath();
    ctx.moveTo(x, y + topRadius);
    ctx.quadraticCurveTo(x, y, x + topRadius, y);
    ctx.lineTo(x + w - topRadius, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + topRadius);
    ctx.lineTo(x + w, creamBottomY - offset);
    ctx.quadraticCurveTo(W / 2, creamBottomY + 90 - offset, x, creamBottomY - offset);
    ctx.closePath();
    ctx.stroke();
  };

  const goldGrad = ctx.createLinearGradient(0, 0, W, 0);
  goldGrad.addColorStop(0, THEME.colors.goldDark);
  goldGrad.addColorStop(0.5, THEME.colors.goldLight);
  goldGrad.addColorStop(1, THEME.colors.goldDark);

  drawFrame(10, 2, THEME.colors.gold);
  drawFrame(22, 5, goldGrad);
};

const drawBottomCurves = (ctx) => {
  const { width: W, height: H } = CANVAS;

  const goldGrad = ctx.createLinearGradient(0, 0, W, 0);
  goldGrad.addColorStop(0, THEME.colors.goldDark);
  goldGrad.addColorStop(0.5, THEME.colors.goldLight);
  goldGrad.addColorStop(1, THEME.colors.goldDark);

  ctx.strokeStyle = goldGrad;
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(70, H - 145);
  ctx.quadraticCurveTo(W / 2, H - 35, W - 70, H - 145);
  ctx.stroke();

  ctx.strokeStyle = THEME.colors.goldLight;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(95, H - 140);
  ctx.quadraticCurveTo(W / 2, H - 50, W - 95, H - 140);
  ctx.stroke();
};

const drawCelebrationLogo = (ctx) => {
  const cx = CANVAS.width / 2;
  const cy = LAYOUT.logoY;
  const { gold, goldLight, green, white } = THEME.colors;

  // Stars
  [-1, 0, 1].forEach((i) => shapes.star(ctx, cx + i * 28, cy - 115, 7, gold));

  // Laurels
  shapes.laurel(ctx, cx - 145, cy - 10, gold, false);
  shapes.laurel(ctx, cx + 145, cy - 10, gold, true);

  // "100"
  ctx.fillStyle = green;
  ctx.font = `bold 110px ${THEME.fonts.serif}`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ['1', '0', '0'].forEach((d, i) => ctx.fillText(d, cx - 70 + i * 65, cy - 30));
  ctx.textBaseline = 'alphabetic';

  // Tiny book
  drawTinyBook(ctx, cx + 28, cy - 75);

  // YEARS label
  canvasUtils.text(ctx, 'YEARS', cx, cy + 38, {
    font: `bold 22px ${THEME.fonts.serif}`,
    color: green,
  });

  // CELEBRATION ribbon
  const ribW = 200, ribH = 32;
  const rx = cx - ribW / 2, ry = cy + 55;

  ctx.fillStyle = gold;
  ctx.beginPath();
  ctx.moveTo(rx, ry);
  ctx.lineTo(rx + ribW, ry);
  ctx.lineTo(rx + ribW + 14, ry + ribH / 2);
  ctx.lineTo(rx + ribW, ry + ribH);
  ctx.lineTo(rx, ry + ribH);
  ctx.lineTo(rx - 14, ry + ribH / 2);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = goldLight;
  ctx.fillRect(rx + 4, ry + 4, ribW - 8, 3);

  canvasUtils.text(ctx, 'CELEBRATION', cx, ry + ribH / 2, {
    font: `bold 17px ${THEME.fonts.serif}`,
    color: white,
    baseline: 'middle',
  });

  shapes.ornamentLine(ctx, cx, cy + 110, 130, gold);
};

const drawTinyBook = (ctx, cx, cy) => {
  const { gold, goldLight } = THEME.colors;

  ctx.fillStyle = gold;
  ctx.beginPath();
  ctx.moveTo(cx - 24, cy);
  ctx.lineTo(cx, cy - 14);
  ctx.lineTo(cx + 24, cy);
  ctx.lineTo(cx, cy + 10);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = goldLight;
  ctx.beginPath();
  ctx.moveTo(cx - 20, cy - 1);
  ctx.lineTo(cx, cy - 11);
  ctx.lineTo(cx + 20, cy - 1);
  ctx.lineTo(cx, cy + 7);
  ctx.closePath();
  ctx.fill();

  ctx.strokeStyle = gold;
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(cx, cy - 11);
  ctx.lineTo(cx, cy + 7);
  ctx.stroke();
};

const drawTitle = (ctx, location) => {
  const cx = CANVAS.width / 2;
  canvasUtils.text(ctx, location || 'Location', cx, LAYOUT.titleY, {
    font: `bold 60px ${THEME.fonts.serif}`,
    color: THEME.colors.greenDark,
  });
  shapes.ornamentLine(ctx, cx, LAYOUT.titleY + 35, 320, THEME.colors.gold);
};

const drawPhotoRings = (ctx) => {
  const cx = CANVAS.width / 2;
  const cy = LAYOUT.photoY;
  const r = LAYOUT.photoRadius;
  const { gold, goldDark, goldLight, green } = THEME.colors;

  ctx.strokeStyle = gold;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(cx, cy, r + 32, 0, Math.PI * 2);
  ctx.stroke();

  ctx.strokeStyle = goldDark;
  ctx.lineWidth = 2;
  ctx.setLineDash([2, 7]);
  ctx.beginPath();
  ctx.arc(cx, cy, r + 22, 0, Math.PI * 2);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.strokeStyle = green;
  ctx.lineWidth = 9;
  ctx.beginPath();
  ctx.arc(cx, cy, r + 8, 0, Math.PI * 2);
  ctx.stroke();

  ctx.strokeStyle = goldLight;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(cx, cy, r + 2, 0, Math.PI * 2);
  ctx.stroke();
};

const drawPhoto = async (ctx, photoUrl) => {
  const cx = CANVAS.width / 2;
  const cy = LAYOUT.photoY;
  const r = LAYOUT.photoRadius;

  if (photoUrl) {
    try {
      const img = await canvasUtils.loadImage(photoUrl);
      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, cy, r, 0, Math.PI * 2);
      ctx.clip();
      const ratio = Math.max((r * 2) / img.width, (r * 2) / img.height);
      const dw = img.width * ratio;
      const dh = img.height * ratio;
      ctx.drawImage(img, cx - dw / 2, cy - dh / 2, dw, dh);
      ctx.restore();
    } catch {
      // fall through to placeholder
    }
  } else {
    ctx.fillStyle = '#e5e7eb';
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.fill();
  }

  shapes.sideOrnament(ctx, cx - r - 38, cy, THEME.colors.gold);
  shapes.sideOrnament(ctx, cx + r + 38, cy, THEME.colors.gold);
};

const drawRibbon = (ctx) => {
  const cx = CANVAS.width / 2;
  const ribbonW = 540, ribbonH = 88;
  const rx = cx - ribbonW / 2;
  const ry = LAYOUT.ribbonY;
  const { green, greenDark, goldLight, cream } = THEME.colors;

  // Tails
  ctx.fillStyle = greenDark;
  [-1, 1].forEach((dir) => {
    const baseX = dir === -1 ? rx : rx + ribbonW;
    const offset = dir * 55;
    const innerOffset = dir * -18;
    const midOffset = dir * 28;
    ctx.beginPath();
    ctx.moveTo(baseX + offset, ry + 12);
    ctx.lineTo(baseX - innerOffset, ry + 8);
    ctx.lineTo(baseX - innerOffset, ry + ribbonH);
    ctx.lineTo(baseX + offset, ry + ribbonH + 22);
    ctx.lineTo(baseX + (dir === -1 ? -28 : 28) - midOffset + midOffset, ry + (ribbonH + 22) / 2);
    ctx.closePath();
    ctx.fill();
  });

  // Body
  ctx.fillStyle = green;
  canvasUtils.roundRect(ctx, rx, ry, ribbonW, ribbonH, 4);
  ctx.fill();

  // Inner border
  ctx.strokeStyle = goldLight;
  ctx.lineWidth = 2.5;
  canvasUtils.roundRect(ctx, rx + 8, ry + 8, ribbonW - 16, ribbonH - 16, 3);
  ctx.stroke();

  canvasUtils.text(ctx, '• Gift of Reading •', cx, ry + ribbonH / 2, {
    font: `italic bold 46px ${THEME.fonts.serif}`,
    color: cream,
    baseline: 'middle',
  });
};

const drawFooterText = (ctx, location, userName) => {
  const cx = CANVAS.width / 2;
  const { gold, goldLight, cream, white } = THEME.colors;

  canvasUtils.text(ctx, 'Presented by', cx, 1140, {
    font: `italic 28px ${THEME.fonts.serif}`,
    color: goldLight,
  });

  ctx.strokeStyle = gold;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(cx - 60, 1155);
  ctx.lineTo(cx + 60, 1155);
  ctx.stroke();

  canvasUtils.text(ctx, location || 'Location', cx, 1195, {
    font: `bold 34px ${THEME.fonts.serif}`,
    color: cream,
  });

  drawNameOrnament(ctx, cx, 1255, 380);

  canvasUtils.text(ctx, userName || 'Participant', cx, 1320, {
    font: `bold 46px ${THEME.fonts.serif}`,
    color: white,
  });
};

const drawNameOrnament = (ctx, cx, cy, width) => {
  const { goldLight } = THEME.colors;
  const grad = ctx.createLinearGradient(cx - width / 2, 0, cx + width / 2, 0);
  grad.addColorStop(0, 'rgba(232,201,122,0)');
  grad.addColorStop(0.5, goldLight);
  grad.addColorStop(1, 'rgba(232,201,122,0)');

  ctx.strokeStyle = grad;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(cx - width / 2, cy);
  ctx.lineTo(cx - 25, cy);
  ctx.moveTo(cx + 25, cy);
  ctx.lineTo(cx + width / 2, cy);
  ctx.stroke();

  shapes.diamond(ctx, cx, cy, 8, goldLight);
  shapes.diamond(ctx, cx - 18, cy, 4, goldLight);
  shapes.diamond(ctx, cx + 18, cy, 4, goldLight);
};

const drawBookIcon = (ctx) => {
  const cx = CANVAS.width / 2;
  const cy = CANVAS.height - 70;
  const { gold, goldLight } = THEME.colors;

  ctx.strokeStyle = gold;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(cx - 110, cy + 3);
  ctx.quadraticCurveTo(cx - 85, cy - 8, cx - 60, cy + 3);
  ctx.moveTo(cx + 110, cy + 3);
  ctx.quadraticCurveTo(cx + 85, cy - 8, cx + 60, cy + 3);
  ctx.stroke();

  ctx.fillStyle = gold;
  ctx.beginPath();
  ctx.moveTo(cx - 55, cy - 5);
  ctx.lineTo(cx, cy - 22);
  ctx.lineTo(cx + 55, cy - 5);
  ctx.lineTo(cx + 55, cy + 22);
  ctx.lineTo(cx, cy + 12);
  ctx.lineTo(cx - 55, cy + 22);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = goldLight;
  ctx.beginPath();
  ctx.moveTo(cx - 50, cy - 2);
  ctx.lineTo(cx, cy - 18);
  ctx.lineTo(cx + 50, cy - 2);
  ctx.lineTo(cx + 50, cy + 18);
  ctx.lineTo(cx, cy + 8);
  ctx.lineTo(cx - 50, cy + 18);
  ctx.closePath();
  ctx.fill();

  ctx.strokeStyle = gold;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(cx, cy - 18);
  ctx.lineTo(cx, cy + 8);
  ctx.stroke();
};

// ============================================================
// MAIN RENDERER
// ============================================================
const renderFrame = async (ctx, { photoUrl, userName, location }) => {
  ctx.canvas.width = CANVAS.width;
  ctx.canvas.height = CANVAS.height;

  drawBackground(ctx);
  drawCreamPanel(ctx);
  drawGoldFrame(ctx);
  drawBottomCurves(ctx);
  drawCelebrationLogo(ctx);
  drawTitle(ctx, location);
  drawPhotoRings(ctx);
  await drawPhoto(ctx, photoUrl);
  drawRibbon(ctx);
  drawFooterText(ctx, location, userName);
  drawBookIcon(ctx);
};

// ============================================================
// REACT COMPONENT
// ============================================================
const styles = {
  wrapper: { textAlign: 'center', marginTop: 16 },
  canvasFrame: {
    display: 'inline-block',
    maxWidth: '100%',
    borderRadius: 12,
    overflow: 'hidden',
    boxShadow: '0 20px 60px rgba(0,0,0,0.18)',
    background: THEME.colors.cream,
  },
  canvas: { display: 'block', width: '100%', maxWidth: 480, height: 'auto' },
  buttonWrap: { marginTop: 24 },
  button: (ready) => ({
    background: `linear-gradient(135deg, ${THEME.colors.green} 0%, ${THEME.colors.greenDark} 100%)`,
    color: '#fff',
    border: 'none',
    padding: '14px 36px',
    borderRadius: 50,
    fontSize: '1rem',
    fontWeight: 600,
    cursor: ready ? 'pointer' : 'not-allowed',
    opacity: ready ? 1 : 0.6,
    boxShadow: '0 8px 20px rgba(13,93,54,0.3)',
    letterSpacing: '0.5px',
    transition: 'transform 0.2s',
  }),
};

const PhotoFrame = ({ photo, userName, location }) => {
  const canvasRef = useRef(null);
  const [photoUrl, setPhotoUrl] = useState(null);
  const [isReady, setIsReady] = useState(false);

  // Manage object URL for the uploaded photo
  useEffect(() => {
    if (!photo) {
      setPhotoUrl(null);
      return;
    }
    const url = URL.createObjectURL(photo);
    setPhotoUrl(url);
    return () => URL.revokeObjectURL(url);
  }, [photo]);

  // Render frame whenever inputs change
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    let cancelled = false;
    setIsReady(false);

    (async () => {
      const ctx = canvas.getContext('2d');
      await renderFrame(ctx, { photoUrl, userName, location });
      if (!cancelled) setIsReady(true);
    })();

    return () => {
      cancelled = true;
    };
  }, [photoUrl, userName, location]);

  const handleDownload = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const safeName = (userName || 'frame').replace(/\s+/g, '-');
    const link = document.createElement('a');
    link.download = `gift-of-reading-${safeName}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  }, [userName]);

  return (
    <div style={styles.wrapper}>
      <div style={styles.canvasFrame}>
        <canvas ref={canvasRef} style={styles.canvas} />
      </div>

      <div style={styles.buttonWrap}>
        <button
          onClick={handleDownload}
          disabled={!isReady}
          style={styles.button(isReady)}
          onMouseOver={(e) => isReady && (e.currentTarget.style.transform = 'translateY(-2px)')}
          onMouseOut={(e) => (e.currentTarget.style.transform = 'translateY(0)')}
        >
          ⬇ Download Frame
        </button>
      </div>
    </div>
  );
};

export default PhotoFrame;
